local CoWait = CS.Engine.Lib.CoWait
local util = require 'XLua.util'
local UIModule = CS.Engine.UI.UIModule
local KTool = CS.Engine.Lib.KTool
local cs_coroutine = require 'XLua.cs_coroutine'
local TowerQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TowerQuestComponent)
local OverseaTowerUtils = import('Game.UI.FightReady.OverseaTower.OverseaTowerUtils')
local CountDownTime = 2592000 --30 * 86400 30天的秒数
local CDTimerModule = CS.Engine.Modules.CDTimerModule
local KCookie = CS.Engine.Lib.KCookie
local Animation = CS.UnityEngine.Animation

---@class UIOverseaTowerCollectPopup
local UIOverseaTowerCollectPopup = Class("UIOverseaTowerCollectPopup")

function UIOverseaTowerCollectPopup:__init()
    self._rewards = {}
end

function UIOverseaTowerCollectPopup:__delete()
    self._rewards = {}
end

function UIOverseaTowerCollectPopup:Awake()
    SetButtonAction(self.ClickClose, Bind(self, self.OnBtnClose))
    SetButtonAction(self.BtnClose, Bind(self, self.OnBtnClose))
    SetButtonAction(self.BtnExplain, Bind(self, self.OnBtnExplain))
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnDrw))
    KCookie.Set(Constants.UICacheDataKeys.OVERSEA_TOWER_ANIM_CONTROL, "true")
end

function UIOverseaTowerCollectPopup:OnDrw()
    if table.count(self._rewards) <= 0 then
        GameUtils.Toast(localize("暂无奖励可领取"))
        return
    end
    TowerQuestComponent:OverseaClimbingTowerDrawTimeHookRewardsReq(function(rewards)
        self._rewards = {}
        self:FillTitle()
        self:FillRewards()
    end)
end

function UIOverseaTowerCollectPopup:OnBtnClose()
    UIModule.BackDialog()
end

function UIOverseaTowerCollectPopup:OnBtnExplain()
    local vo = OverseaTowerUtils.GetClimbTowerConfigVo(10)
    CfUtils.ShowModuleToast(vo.num)
end

function UIOverseaTowerCollectPopup:FillSelf()
    self:FillTitle()
    self:FillInComeInfo()
    self:FillRewards()

    self:StartTimeDown()
end

function UIOverseaTowerCollectPopup:StartTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end

    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        local time = TowerQuestComponent:GetHookTime()
        if time >= 8 * 3600 then
            --CfUtils.FillText(self.TextDesc, string.format_color_tag(CfUtils.GetTimeHMS( 8 * 3600), "#ff2ea9"))
            CfUtils.FillText(self.TextDesc, localize("已经采集8小时"))
        else
            CfUtils.FillText(self.TextDesc, CfUtils.GetTimeHMS(time))
        end
        CfUtils.SetActive(self.ImgMax, OverseaTowerUtils.IsMaxCollect())
    end, CountDownTime, false, true)
end

function UIOverseaTowerCollectPopup:FillTitle()
    local id = OverseaTowerUtils.GetCurQuestId(Constants.TowerType.Main)
    local vo = OverseaTowerUtils.GetTowerQuestVo(id)
    if vo then
        local maxId = OverseaTowerUtils.GetMaxQuestId(Constants.TowerType.Main)
        local isPassed = OverseaTowerUtils.IsPassQuest(id)
        if checkNumber(id) == maxId and isPassed then
            CfUtils.FillText(self.TextNumber, localize('_num_层收益', { _num_ = checkNumber(vo.storey) }))
        else
            CfUtils.FillText(self.TextNumber, localize('_num_层收益', { _num_ = checkNumber(vo.storey) - 1 }))
        end

    end

    local time = TowerQuestComponent:GetHookTime()
    if time >= 8 * 3600 then
        --CfUtils.FillText(self.TextDesc, string.format_color_tag(CfUtils.GetTimeHMS( 8 * 3600), "#ff2ea9"))
        CfUtils.FillText(self.TextDesc, localize("已经采集8小时"))
    else
        CfUtils.FillText(self.TextDesc, CfUtils.GetTimeHMS(time))
    end

    CfUtils.SetActive(self.ImgMax, OverseaTowerUtils.IsMaxCollect())
end

function UIOverseaTowerCollectPopup:GetPreviewRewards(goodsId)
    local t = {}
    if #self._rewards > 0 then
        for _, v in pairs(self._rewards) do
            if checkNumber(v.from) == goodsId then
                table.insert(t, v)
            end
        end
    end
    print('==>>', #self._rewards, #t)
    return t
end

function UIOverseaTowerCollectPopup:FillInComeInfo()
    local id = OverseaTowerUtils.GetCurQuestId(Constants.TowerType.Main)
    local rewardVo = RewardConfMgr:GetInstance():GetQuestRewardVo(id)

    if rewardVo then
        ---@type TowerQuestVo
        local questVo = OverseaTowerUtils.GetTowerQuestVo(id)
        local lastQuestId = checkNumber(questVo.unlockNum)
        local lastQuestVo = OverseaTowerUtils.GetTowerQuestVo(lastQuestId)
        local t = checkTable(rewardVo.revenueRewardsTime)
        local _t = OverseaTowerUtils.GetAllReward()

        for k, v in pairs(t) do
            local go = self["IncomeNode" .. k]
            CfUtils.SetActive(go, true)
            if go then
                CfUtils.SetActive(go, checkNumber(_t[k].num) > 0)
                CfUtils.FillText(go.transform:Find("Number/TextNumber"), _t[k].num)
                CfUtils.FillText(go.transform:Find("Number/TextDesc"), string.format("/%d", _t[k].time) .. localize("分钟"))
                local parVo = OverseaTowerUtils.GetClimbTowerConfigVo(k + 6)
                if parVo then
                    local tt = string.split(parVo.num, ";")
                    local rewardGroupId = checkNumber(questVo.rewardGroupId) % 100
                    local goodsId = tt[rewardGroupId]   -- 因为这里显示的是已经通关的层数，所以用上一层的questVo
                    if isNull(goodsId) then
                        goodsId = tt[1]
                    end
                    local goodsIconTrans = go.transform:Find("BtnGoodsIcon")
                    SetButtonAction(goodsIconTrans, function()
                        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
                        local idType = GoodsUtils.GetIdType(goodsId)
                        if idType == Constants.IDType.GoodsUsable then
                            local rewards = OverseaTowerUtils.GetTowerRewardPoolVo(lastQuestVo.rewardGroupId)
                            if #rewards > 0 then
                                GameUtils.ShowCommonTipsBoardRewardPreview(goodsIconTrans.gameObject, rewards)
                            end
                        else
                            GameUtils.ShowCommonTipsBoard(goodsIconTrans.gameObject, vo.name, vo.desc, vo.quality, vo.id)
                        end
                    end)
                    CfUtils.FillImage(go.transform:Find("BtnGoodsIcon/ImgGoodsIcon"), GoodsConfMgr:GetInstance():GetPhotoPathById(goodsId))
                end
            end
        end
    end
end

function UIOverseaTowerCollectPopup:FillRewards()
    if self._rewards then
        local emptyNode = self.ScrollView.transform.parent:Find("EmptyNode")
        if emptyNode then
            KTool.SetActive(emptyNode.gameObject, #self._rewards == 0)
            KTool.SetActive(self.ScrollView.gameObject, #self._rewards > 0)
        end
        if #self._rewards > 0 then
            if not self.ScrollView.IsListViewInit then
                self.ScrollView:InitGridView(table.count(self._rewards), Bind(self, self.OnGetItemByIndex))
            else
                GameUtils.ReloadData(self.ScrollView, table.count(self._rewards))
            end
        end
    end
end

function UIOverseaTowerCollectPopup:PlayDelayShowAnimation(go, showAnimName, afterAnimation)
    if not go then
        return
    end
    ---@type UnityEngine.Animation
    local animator = go.transform:GetComponent(typeof(Animation))
    if not animator then
        return
    end
    animator:PlayQueued(showAnimName)
    animator:PlayQueued(afterAnimation)
end

function UIOverseaTowerCollectPopup:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local luaIndex = index + 1
    local cell = listView:NewListViewItem("Cell")
    local data = self._rewards[luaIndex]

    local go = cell.gameObject.transform:Find("GoodNode")
    CfUtils.RefeshGoodGo2(go, data.goodsId, data.num, nil, nil, function()
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(data.goodsId)
        GameUtils.ShowCommonTipsBoard(go, vo.name, vo.desc, vo.quality, vo.id)
    end)
    local animationRoot = cell.gameObject.transform:Find("RewardChange")
    if animationRoot then
        CfUtils.SetActive(animationRoot, false)
    end
    if checkNumber(data.from) > 0 then
        local from = checkNumber(data.from) % 100
        if animationRoot then
            ---@type GoodsVo
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(data.goodsId)
            if vo then
                local imgBg = animationRoot:Find("ImgBg")
                local imgIcon = animationRoot:Find("ImgIcon")
                CfUtils.SetUISwitchImage(imgIcon, from)
                CfUtils.FillImage(imgBg, GoodsUtils.GetGoodsBackgroundByQualityType(vo.quality, false, false))
            end
            CfUtils.SetActive(animationRoot, true)
            self:PlayDelayShowAnimation(animationRoot, "OverseaTowerCollectPopup_RewardChange", "OverseaTowerCollectRewardCellHide")
        end
    end
    return cell
end

