function UIOverseaTowerCollectPopup:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        TowerQuestComponent:OverseaClimbingTowerQuestTimeHookRewardsReq(function(rewards)
            self._rewards = {}
            for k, v in pairs(rewards) do
                if checkNumber(v.num) > 0 then
                    table.insert(self._rewards, v)
                end
            end
            self:FillSelf()
        end)
    end))
    return coWait
end

function UIOverseaTowerCollectPopup:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if not isNull(self._timeDown) then
            CDTimerModule.GetInstance():RemoveCD(self._timeDown)
            self._timeDown = nil
        end

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIOverseaTowerCollectPopup
